import 'package:theme_core/theme_core.dart';
import '../../domain/entities/user_profile.dart';

/// Writes the base theme files (wallpapers, clock widget, description and
/// plugin config); falls back to the user profile's name and tag.
/// System app modules are generated by `ExportSystemModulesUseCase`.
class ExportModuleUseCase {
  const ExportModuleUseCase();

  Future<Failure?> call({
    required UserProfile profile,
    required ThemeLayout layout,
    required String themeName,
    required String wallpaperSourcePath,
    String? lockWallpaperSourcePath,
    String? designerName,
    String? authorTag,
    String uiVersion = '17',
  }) async {
    try {
      await const ThemeBaseWriter().write(
        layout: layout,
        title: themeName,
        designer: designerName?.isNotEmpty == true
            ? designerName!
            : profile.displayName,
        authorTag: authorTag?.isNotEmpty == true
            ? authorTag!
            : profile.authorTag,
        wallpaperSourcePath: wallpaperSourcePath,
        lockWallpaperSourcePath: lockWallpaperSourcePath,
        uiVersion: uiVersion,
      );
      return null;
    } catch (e) {
      return ExportFailure(e.toString());
    }
  }
}
